const fq=e=>{const y=+e.slice(0,4),m=+e.slice(5,7);return m<=2?`Q4 FY${String(y).slice(2)}`:`Q${m<=5?1:m<=8?2:3} FY${String(y+1).slice(2)}`};
const cq=e0=>{const dt=new Date(Date.parse(e0)-45*864e5),e=dt.toISOString().slice(0,10),y=e.slice(2,4),m=+e.slice(5,7);return `${['Q1','Q1','Q1','Q2','Q2','Q2','Q3','Q3','Q3','Q4','Q4','Q4'][m-1]}'${y}`};
const B$=(v,d=1)=>v==null?'—':(v<0?'−':'')+(LG==='zh'?'$'+(Math.abs(v)/1e8).toLocaleString('en-US',{maximumFractionDigits:0})+' 亿':'$'+(Math.abs(v)/1e9).toFixed(d)+'bn');
