const P=(v,d=1)=>v==null||!isFinite(v)?'—':(v*100).toFixed(d)+'%';const N=v=>v==null?'—':Math.round(v).toLocaleString('en-US');
const sg=v=>v==null?'':(v>=0?'pos':'neg');const pm=(v,d=1)=>v==null?'—':(v>=0?'+':'')+(v*100).toFixed(d)+'%';
